CREATE TABLE public.logical_read_inputs(id integer PRIMARY KEY, label varchar(12), divisor integer);
INSERT INTO public.logical_read_inputs VALUES (1,'first',2),(2,NULL,5),(3,'bad',0),(4,'later',1);
WITH input AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,label,10/divisor AS quotient FROM input;
WITH input AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,label,10/divisor AS quotient FROM input LIMIT 0;
WITH input AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,label,10/divisor AS quotient FROM input LIMIT 2;
WITH input AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,label,10/divisor AS quotient FROM input LIMIT 3;
WITH input AS (SELECT id,label,divisor FROM public.logical_read_inputs WHERE id<3) SELECT id,label,10/divisor AS quotient FROM input ORDER BY id;
WITH input AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,label,10/divisor AS quotient FROM input LIMIT 1 OFFSET 1;
WITH input AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,label,10/divisor AS quotient FROM input LIMIT 1 OFFSET 2;
WITH input AS (SELECT id,divisor FROM public.logical_read_inputs) SELECT count(*) FROM input WHERE 10/divisor>1;
WITH input AS (SELECT id,divisor FROM public.logical_read_inputs) SELECT count(*) FROM input WHERE id<3 AND 10/divisor>1;
WITH input AS (SELECT id,divisor FROM public.logical_read_inputs WHERE id<3) SELECT count(10/divisor), count(divisor), count(*) FROM input;
WITH input AS (SELECT id FROM public.logical_read_inputs) SELECT count(1/0) FROM input;
WITH input AS (SELECT id FROM public.logical_read_inputs) SELECT count(*) FILTER (WHERE 1/0>0) FROM input;
WITH input AS (SELECT id FROM public.logical_read_inputs) SELECT count(1/0) FROM input LIMIT 0;
WITH input AS (SELECT id FROM public.logical_read_inputs) SELECT count(CASE WHEN false THEN 1/0 ELSE id END) FROM input;
WITH input AS MATERIALIZED (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,label,10/divisor AS quotient FROM input LIMIT 2;
WITH input AS NOT MATERIALIZED (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,label,10/divisor AS quotient FROM input LIMIT 2;
WITH raw AS (SELECT id,label,divisor FROM public.logical_read_inputs), safe AS (SELECT id,label,divisor FROM raw WHERE id<3) SELECT id,label,10/divisor AS quotient FROM safe ORDER BY id;
WITH unreferenced AS (SELECT 1/0), input AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,label,10/divisor AS quotient FROM input LIMIT 2;
WITH input(i,l,d) AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT input.i AS "Row ID", l AS "Row Label", 10/input.d AS quotient FROM input LIMIT 2;
SELECT q.id,q.label,10/q.divisor AS quotient FROM (SELECT id,label,divisor FROM public.logical_read_inputs) AS q LIMIT 2;
SELECT q.id,q.label,10/q.divisor AS quotient FROM (SELECT id,label,divisor FROM public.logical_read_inputs) AS q LIMIT 3;
SELECT count(*) FROM (SELECT id,divisor FROM public.logical_read_inputs) AS q WHERE 10/q.divisor>1;
WITH input AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,id+1 AS next_id FROM input WHERE label IS NULL;
WITH input AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT missing_column FROM input LIMIT 0;
BEGIN;
SAVEPOINT read_problem;
WITH input AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,label,10/divisor AS quotient FROM input LIMIT 3;
SELECT count(*) FROM public.logical_read_inputs;
ROLLBACK TO SAVEPOINT read_problem;
WITH input AS (SELECT id,label,divisor FROM public.logical_read_inputs) SELECT id,label,10/divisor AS quotient FROM input LIMIT 2;
COMMIT;
DROP TABLE public.logical_read_inputs;
